effect.shader:
float gmHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmNoise(vec2 p){
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(gmHash(i), gmHash(i + vec2(1.0, 0.0)), u.x),
             mix(gmHash(i + vec2(0.0, 1.0)), gmHash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float gmFbm(vec2 p){
  float a = 0.5, s = 0.0;
  for (int i = 0; i < 5; i++){ s += a * gmNoise(p); p *= 2.03; a *= 0.5; }
  return s;
}
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec2 p = uv * scale;
  p.y -= acTime * speed;
  float n = gmFbm(p + vec2(0.0, -uv.y * 3.0));
  float flame = pow(clamp(1.0 - uv.y, 0.0, 1.0), 1.6) * n * heat;
  vec3 fire = mix(vec3(1.0, 0.15, 0.0), vec3(1.0, 0.95, 0.4), clamp(flame, 0.0, 1.0));
  fire *= clamp(flame, 0.0, 1.5);
  vec3 col = c + fire * amount * mixAmt;
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
